"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[36174],{44186:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>a,default:()=>c,frontMatter:()=>h,metadata:()=>i,toc:()=>d});var s=n(31085),o=n(71184);const h={sidebar_position:20,slug:"/bible/Acts/Acts_20",title:"Acts 20",hide_table_of_contents:!0},a="Acts",i={id:"bible/Acts/Acts 20",title:"Acts 20",description:"Chapter 20",source:"@site/docs/bible/Acts/Acts 20.md",sourceDirName:"bible/Acts",slug:"/bible/Acts/Acts_20",permalink:"/bibleNotes/docs/bible/Acts/Acts_20",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Acts/Acts 20.md",tags:[],version:"current",sidebarPosition:20,frontMatter:{sidebar_position:20,slug:"/bible/Acts/Acts_20",title:"Acts 20",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Acts 19",permalink:"/bibleNotes/docs/bible/Acts/Acts_19"},next:{title:"Acts 21",permalink:"/bibleNotes/docs/bible/Acts/Acts_21"}},r={},d=[{value:"Chapter 20",id:"chapter-20",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,o.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.h1,{id:"acts",children:"Acts"}),"\n",(0,s.jsx)(t.h2,{id:"chapter-20",children:"Chapter 20"}),"\n",(0,s.jsx)(t.p,{children:"Paul passes through Macedonia and Greece.  He raises a dead man to life at Troas.  His discourse to the clergy of Ephesus."}),"\n",(0,s.jsx)(n,{verse:1,children:"And after the tumult was ceased, Paul calling to him the disciples and exhorting them, took his leave and set forward to go into Macedonia."}),"\n",(0,s.jsx)(n,{verse:2,children:"And when he had gone over those parts and had exhorted them with many words, he came into Greece:"}),"\n",(0,s.jsx)(n,{verse:3,children:"Where, when he had spent three months, the Jews laid wait for him, as he was about to sail into Syria. So he took a resolution to return through Macedonia."}),"\n",(0,s.jsx)(n,{verse:4,children:"And there accompanied him Sopater, the son of Pyrrhus, of Berea: and of the Thessalonians, Aristarchus and Secundus: and Gaius of Derbe and Timothy: and of Asia, Tychicus and Trophimus."}),"\n",(0,s.jsx)(n,{verse:5,children:"These, going before, stayed for us at Troas."}),"\n",(0,s.jsx)(n,{verse:6,children:"But we sailed from Philippi after the days of the azymes and came to them to Troas in five days, where we abode seven days."}),"\n",(0,s.jsx)(n,{verse:7,children:"And on the first day of the week, when we were assembled to break bread, Paul discoursed with them, being to depart on the morrow. And he continued his speech until midnight."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: And on the first day of the week...Here St. Chrysostom and many other interpreters of the scripture explain, that the Christians even at this time, must have changed the sabbath into the first day of the week, (the Lord's day,) as all Christians now keep it. This change was undoubtedly made by the authority of the church; hence the exercise of the power, which Christ had given to her: for he is Lord of the sabbath."})}),"\n",(0,s.jsx)(n,{verse:8,children:"And there were a great number of lamps in the upper chamber where we were assembled."}),"\n",(0,s.jsx)(n,{verse:9,children:"And a certain young man named Eutychus, sitting on the window, being oppressed with a deep sleep (as Paul was long preaching), by occasion of his sleep fell from the third loft down and was taken up dead."}),"\n",(0,s.jsx)(n,{verse:10,children:"To whom, when Paul had gone down, he laid himself upon him and, embracing him, said: Be not troubled, for his soul is in him."}),"\n",(0,s.jsx)(n,{verse:11,children:"Then going up and breaking bread and tasting and having talked a long time to them, until daylight, so he departed."}),"\n",(0,s.jsx)(n,{verse:12,children:"And they brought the youth alive and were not a little comforted."}),"\n",(0,s.jsx)(n,{verse:13,children:"But we going aboard the ship, sailed to Assos, being there to take in Paul. For so he had appointed, himself purposing to travel by land."}),"\n",(0,s.jsx)(n,{verse:14,children:"And when he had met with us at Assos, we took him in and came to Mitylene."}),"\n",(0,s.jsx)(n,{verse:15,children:"And sailing thence, the day following we came over against Chios: and the next day we arrived at Samos: and the day following we came to Miletus."}),"\n",(0,s.jsx)(n,{verse:16,children:"For Paul had determined to sail by Ephesus, lest he should be stayed any time in Asia. For he hasted. if it were possible for him, to keep the day of Pentecost at Jerusalem."}),"\n",(0,s.jsx)(n,{verse:17,children:"And sending from Miletus to Ephesus, he called the ancients of the church."}),"\n",(0,s.jsx)(n,{verse:18,children:"And when they were come to him and were together, he said to them: You know from the first day that I came into Asia, in what manner I have been with you, for all the time."}),"\n",(0,s.jsx)(n,{verse:19,children:"Serving the Lord with all humility and with tears and temptations which befell me by the conspiracies of the Jews:"}),"\n",(0,s.jsx)(n,{verse:20,children:"How I have kept back nothing that was profitable to you, but have preached it to you, and taught you publicly, and from house to house,"}),"\n",(0,s.jsx)(n,{verse:21,children:"Testifying both to Jews and Gentiles penance towards God and faith in our Lord Jesus Christ."}),"\n",(0,s.jsx)(n,{verse:22,children:"And now, behold, being bound in the spirit, I go to Jerusalem: not knowing the things which shall befall me there:"}),"\n",(0,s.jsx)(n,{verse:23,children:"Save that the Holy Ghost in every city witnesseth to me, saying: That bands and afflictions wait for me at Jerusalem."}),"\n",(0,s.jsx)(n,{verse:24,children:"But I fear none of these things, neither do I count my life more precious than myself, so that I may consummate my course and the ministry of the word which I received from the Lord Jesus, to testify the gospel of the grace of God."}),"\n",(0,s.jsx)(n,{verse:25,children:"And now behold, I know that all you, among whom I have gone preaching the kingdom of God, shall see my face no more."}),"\n",(0,s.jsx)(n,{verse:26,children:"Wherefore I take you to witness this day that I am clear from the blood of all men."}),"\n",(0,s.jsx)(n,{verse:27,children:"For I have not spread to declare unto you all, the counsel of God."}),"\n",(0,s.jsx)(n,{verse:28,children:"Take heed to yourselves and to the whole flock, wherein the Holy Ghost hath placed you bishops, to rule the Church of God which he hath purchased with his own blood."}),"\n",(0,s.jsx)(n,{verse:29,children:"I know that after my departure ravening wolves will enter in among you, not sparing the flock."}),"\n",(0,s.jsx)(n,{verse:30,children:"And of your own selves shall arise men speaking perverse things, to draw away disciples after them."}),"\n",(0,s.jsx)(n,{verse:31,children:"Therefore watch, keeping in memory that for three years I ceased not with tears to admonish every one of you, night and day."}),"\n",(0,s.jsx)(n,{verse:32,children:"And now I commend you to God and to the word of his grace, who is able to build up and to give an inheritance among all the sanctified."}),"\n",(0,s.jsx)(n,{verse:33,children:"I have not coveted any man's silver, gold or apparel, as"}),"\n",(0,s.jsx)(n,{verse:34,children:"You yourselves know. For such things as were needful for me and them that are with me, these hands have furnished."}),"\n",(0,s.jsx)(n,{verse:35,children:"I have shewed you all things, how that so labouring you ought to support the weak and to remember the word of the Lord Jesus, how he said: It is a more blessed thing to give, rather than to receive."}),"\n",(0,s.jsx)(n,{verse:36,children:"And when he had said these things, kneeling down, he prayed with them all."}),"\n",(0,s.jsx)(n,{verse:37,children:"And there was much weeping among them all. And falling on the neck of Paul, they kissed him,"}),"\n",(0,s.jsx)(n,{verse:38,children:"Being grieved most of all for the word which he had said, that they should see his face no more. And they brought him on his way to the ship."})]})}function c(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>a,x:()=>i});var s=n(14041);const o={},h=s.createContext(o);function a(e){const t=s.useContext(h);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),s.createElement(h.Provider,{value:t},e.children)}}}]);